src/index.css.content:
@import "./variables.css";

:root {
  font-family: "Poppins", "Inter", sans-serif;
  line-height: 1.6;
  font-weight: 400;
  color-scheme: dark;
  color: var(--text-primary);
  background-color: var(--background);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

* {
  font-family: "Poppins", "Inter", sans-serif;
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: linear-gradient(135deg, #0a0a0f 0%, #1a1a2e 100%);
  min-height: 100vh;
}
.active {
  position: fixed;
  width: 100%;
  height: 100%;
  overflow: hidden;
  inset: 0;
}

input {
  outline: none;
  border: none;
}
input:focus {
  outline: none;
  border: none;
}
.input {
  border-radius: 15px 0 0 15px;
}
.btn {
  border-radius: 0 15px 15px 0;
}

.flw-item {
  width: calc(16.66% - 0.5rem);
  margin: 0.7rem 0;
  position: relative;
}
.gradient-text {
  font-weight: 800;
  background: linear-gradient(
    90deg,
    #fff,
    var(--primary)
  ); /* Gradient colors */
  -webkit-background-clip: text; /* Clips the gradient to the text */
  background-clip: text;
  -webkit-text-fill-color: transparent; /* Makes the text transparent */
  text-align: center;
}
.active {
  position: fixed;
  inset: 0;
  backdrop-filter: blur(10px);
  background-color: #222831b4;
  z-index: 5000;
}
.bg-active {
  position: fixed;
  inset: 0;
  overflow: hidden;
}
.sidebar {
  scrollbar-width: none;
}
.cover-wrapper {
  position: absolute;
  height: 50%;
  inset: 0;
  overflow: hidden;
}
.cover {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  filter: blur(2px);
  transform: scale(1.2);
  opacity: 0.2;
}
.logo h1 {
  position: relative;
  overflow: hidden;
  white-space: nowrap;
}

@media screen and (max-width: 1023px) {
  .flw-item {
    width: calc(25% - 0.5rem) !important;
  }
}
@media screen and (max-width: 1400px) {
  .flw-item {
    width: calc(25% - 0.5rem) !important;
  }
}
@media screen and (max-width: 759px) {
  .flw-item {
    width: calc(33.33% - 0.5rem) !important;
  }
  .swiper-button-prev {
    display: none;
  }
  .swiper-button-next {
    display: none;
  }
}
@media screen and (max-width: 479px) {
  .flw-item {
    width: calc(50% - 0.5rem) !important;
  }
  .posterImg {
    width: 60%;
  }
}

.opacity-overlay {
  height: 250px;
  width: 100%;
  background: linear-gradient(
    to bottom,
    rgba(4, 21, 45, 0) 0%,
    var(--background) 79.17%
  );
  position: absolute;
  bottom: 0;
}
.rounded-child > p:first-child {
  border-radius: 2px 0 0 2px;
}
.rounded-child > p:last-child {
  border-radius: 0 2px 2px 0;
}
.lightBorder {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin: 10px 0;
}
.gray {
  color: #fff;
  opacity: 0.5;
}

src/components/Player.jsx.content:
/* eslint-disable react/prop-types */
import { useEffect, useRef, useState } from "react";
import {
  TbPlayerTrackPrevFilled,
  TbPlayerTrackNextFilled,
} from "react-icons/tb";

const Player = ({
  episodeId,
  currentEp,
  changeEpisode,
  hasNextEp,
  hasPrevEp,
}) => {
  const [category, setCategory] = useState("sub");
  const [server, setServer] = useState("vidWish");

  const changeCategory = (newType) => {
    if (newType !== category) {
      setCategory(newType);
    }
  };
  function changeServer(newServer) {
    if (newServer !== server) setServer(newServer);
  }

  return (
    <>
      <div className="w-full bg-background aspect-video relative rounded-sm  max-w-screen-xl overflow-hidden">
        <iframe
          src={`https://${
            server === "vidWish" ? "vidwish.live" : "megaplay.buzz"
          }/stream/s-2/${episodeId.split("ep=").pop()}/${category}`}
          width="100%"
          height="100%"
          allowFullScreen
        ></iframe>
      </div>
      <div className="category flex flex-wrap flex-col sm:flex-row items-center justify-center  sm:justify-between px-2 md:px-20 gap-3 bg-lightbg py-2">
        <div className="servers flex gap-4">
          <button
            onClick={() => changeServer("vidWish")}
            className={`${
              server === "vidWish"
                ? "bg-primary text-black"
                : "bg-btnbg  text-white"
            } px-2 py-1 rounded text-sm font-semibold`}
          >
            vidwish
          </button>
          <button
            onClick={() => changeServer("megaPlay")}
            className={`${
              server === "megaPlay"
                ? "bg-primary text-black"
                : "bg-btnbg  text-white"
            } px-2 py-1 rounded text-sm font-semibold`}
          >
            megaplay
          </button>
        </div>
        <div className="flex gap-5">
          <div className="sound flex gap-3">
            {["sub", "dub"].map((type) => (
              <button
                key={type}
                onClick={() => changeCategory(type)}
                className={`${
                  category === type
                    ? "bg-primary text-black"
                    : "bg-btnbg  text-white"
                } px-2 py-1 rounded text-sm font-semibold`}
              >
                {type.toUpperCase()}
              </button>
            ))}
          </div>
          <div className="btns flex gap-4">
            {hasPrevEp && (
              <button
                title="prev"
                className="prev bg-primary px-2 py-1 rounded-md text-black"
                onClick={() => changeEpisode("prev")}
              >
                <TbPlayerTrackPrevFilled />
              </button>
            )}
            {hasNextEp && (
              <button
                title="next"
                className="next bg-primary px-2 py-1 rounded-md text-black"
                onClick={() => changeEpisode("next")}
              >
                <TbPlayerTrackNextFilled />
              </button>
            )}
          </div>
        </div>
        <div className="flex flex-col">
          <p className="text-gray-400">
            you are watching Episode {currentEp.episodeNumber}
          </p>
          {currentEp.isFiller && (
            <p className="text-red-400">your are watching filler Episode 👻</p>
          )}
        </div>
      </div>
    </>
  );
};

export default Player;

src/pages/CharactersPage.jsx.content:
import React, { useEffect } from "react";
import { Link, useParams } from "react-router-dom";
import { useInfiniteApi } from "../services/useApi";
import Loader from "../components/Loader";
import Footer from "../components/Footer";
import Heading from "../components/Heading";
import Pagination from "../components/Pagination";

const CharactersPage = () => {
  const { id } = useParams();

  const { data, isError, error, isLoading, hasNextPage, fetchNextPage } =
    useInfiniteApi(`/characters/${id}?page=`);

  const pages = data?.pages;
  return (
    <>
      <main className="pt-14 pb-5 mx-auto max-w-[800px]">
        {pages && !isLoading ? (
          <>
            <Heading>charcters and voice actors</Heading>
            <div className="grid mb-4 mx-1 mt-2 grid-cols-12 gap-2">
              {pages?.map((page, pageIndex) => (
                <React.Fragment key={pageIndex}>
                  {page.data.response.map((item) => (
                    <div
                      key={item.id}
                      className="wrapper flex px-1 py-3 rounded-sm items-center justify-between bg-lightbg col-span-12 "
                    >
                      <div className="left gap-2 flex items-center">
                        <Link to={`/${item.id.replace(":", "/")}`}>
                          <div className="poster size-9 overflow-hidden rounded-[50%]">
                            <img
                              className="h-full w-full object-cover"
                              src={item.imageUrl}
                              alt={item.name}
                            />
                          </div>
                        </Link>
                        <div className="flex flex-col">
                          <Link to={`/${item.id.replaceAll(":", "/")}`}>
                            <h4 className="text-xs hover:text-primary">
                              {item.name}
                            </h4>
                          </Link>
                          <span className="text-xs text-lighttext">
                            {item.role}
                          </span>
                        </div>
                      </div>
                      <div className="right flex items-center gap-2">
                        {item.voiceActors.length !== 0 &&
                          item.voiceActors.map((actor) => (
                            <React.Fragment key={actor.id}>
                              <Link to={`/${actor.id.replace(":", "/")}`}>
                                <div
                                  title={actor.name}
                                  className="poster size-9 rounded-[50%] overflow-hidden"
                                >
                                  <img
                                    loading="lazy"
                                    className="h-full w-full object-center  object-cover"
                                    src={actor.imageUrl}
                                    alt={actor.name}
                                  />
                                </div>
                              </Link>
                            </React.Fragment>
                          ))}
                      </div>
                    </div>
                  ))}
                </React.Fragment>
              ))}
            </div>
            {hasNextPage && (
              <button
                onClick={fetchNextPage}
                className="bg-lightbg mx-auto py-3 w-full hover:text-primary"
              >
                Load More
              </button>
            )}
          </>
        ) : (
          <Loader className="h-[100dvh]" />
        )}
        {/* <Pagination /> */}
      </main>
      <Footer />
    </>
  );
};

export default CharactersPage;

src/components/ThemeToggle.jsx.content:
import { motion } from "framer-motion";
import { FaSun, FaMoon } from "react-icons/fa";
import { useTheme } from "../context/ThemeContext";

const ThemeToggle = () => {
  const { theme, toggleTheme } = useTheme();

  return (
    <motion.button
      whileHover={{ scale: 1.1 }}
      whileTap={{ scale: 0.95 }}
      onClick={toggleTheme}
      className="relative w-12 h-12 rounded-full glass neon-border-hover flex items-center justify-center group transition-all duration-300"
      aria-label="Toggle theme"
    >
      <motion.div
        initial={{ rotate: 0 }}
        animate={{ rotate: theme === 'dark' ? 0 : 180 }}
        transition={{ duration: 0.3 }}
        className="text-xl"
      >
        {theme === 'dark' ? (
          <FaMoon className="text-cyan-400" />
        ) : (
          <FaSun className="text-yellow-400" />
        )}
      </motion.div>
      <div className="absolute inset-0 rounded-full bg-gradient-to-r from-violet-500/20 to-cyan-500/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
    </motion.button>
  );
};

export default ThemeToggle;

